// Content grounded in the existing portfolio, archived case studies, and supplied LOC discussion.
// Outcome language distinguishes delivered design work from unmeasured downstream effects.
const item = (title, body, image, caption) => ({title,body,image,caption});
const insight = (title, observation, principle, response) => ({title,observation,principle,response});
const section = (title, body, extra = {}) => ({title,body,...extra});
export const caseStudies = {
 house: {
  number:'01',slug:'house',client:'U.S. House',title:'Committee Voting Platform',summary:'Designing a new digital experience for complex legislative workflows—from finding a referral to recording a committee vote—and the 30+ component USWDS design system behind it, with tokens, states, and documentation.',tags:['Design systems','Product design','Research','Accessibility'],figma:'https://www.figma.com/design/0W25IhXkLWlhytPD2Gl22g/Omoniyi-Portfolio?node-id=1-136107',
  hero:[['house-filters','Find the work / Committee and date filters narrow the referral list.'],['house-context','Understand the context / A Referral Brief stays beside the work.'],['house-controls','Act with confidence / Explicit Yea, Nay, and Present choices.']],
  facts:[['Client','U.S. House of Representatives'],['Product','Committee Voting Platform'],['Role','UI/UX Designer'],['Timeline','2024–2025'],['Team','Product manager, engineers, QA, House leadership, SMEs'],['Platform','Responsive web application'],['Tools','Figma, Azure DevOps, USWDS'],['My ownership','Research, workflows, prototypes, design system, specifications, user stories and acceptance criteria']],
  proof:[['0 → 1','New digital product'],['3× / week','Working sessions with House leadership'],['30+','Reusable USWDS-based components']],
  sections:[
   section('Making legislative complexity navigable.','The work connected referrals, member rosters, and roll-call voting in one product. I partnered closely with staff and engineering to translate legislative requirements into a usable interface.',{images:[['house-dashboard','Committee Referrals: the shared starting point for finding and managing legislative activity.']]}),
   section('Find. Understand. Act. Complete.','Committee vote information had been collected and displayed inconsistently. A unified product needed to preserve the rules and records behind the work while giving staff a clear starting point.',{items:[item('Locate the right referral','Staff needed a centralized list with useful filters and identifiable bill records.'),item('Keep context available','Sponsors, legislative dates, and referral history needed to remain accessible during decisions.'),item('Make the action explicit','Committee-specific rules had to become clear choices without losing the official record.')],images:[['house-table','Bill numbers, titles, dates, and row-level details give each referral a recognizable place in the workflow.']]}),
   section('Understand the work before drawing the workflow.','Approximately 18 interviews across two research rounds, recurring leadership sessions, and live prototypes helped expose business rules and missing requirements. I used those conversations to connect people, legislative information, and the actions each role needed to take.',{images:[['house-roster','Roster management connects committee membership to the voting workflow.'],['house-context','The Referral Brief exposes the legislative information staff need at the point of review.']]}),
   section('Clarity comes from keeping context close.','Three recurring needs shaped the product’s interaction model.',{items:[insight('Context cannot disappear.','Staff needed legislative information while completing tasks.','Keep decision-support information inside the workflow.','The Referral Brief opens alongside the referral list.'),insight('Complexity needs structure.','Voting rules contained meaningful choices and exceptions.','Organize actions into understandable sections.','Roll-call details separate meeting context, outcome, and representative choices.'),insight('Findability precedes action.','Users first needed to identify and understand a bill.','Create a clear operational starting point.','Committee Referrals combines filters, records, and detail access.')],images:[['house-context','The overlay preserves the referral list behind the brief, keeping the task and its context connected.']]}),
   section('Three decisions that held the workflow together.','The aim was to reduce navigation and interpretation effort while retaining the information legislative work requires.',{items:[item('Give each stage a focused place.','Referrals, roster management, and voting became distinct modules. This adds structure without turning every task into one long form.','house-navigation','The primary navigation names the three operational destinations.'),item('Bring the brief to the decision.','A contextual panel keeps legislative details close. The tradeoff is a denser view, balanced by a focused overlay and a clear way back.','house-context','Referral context is available without abandoning the list.'),item('Let staff tune the table.','Table controls make dense records easier to inspect while preserving a shared data model.','house-manage','Manage Table controls expose options for the referral workspace.')]}),
   section('One product, three connected jobs.','The interface follows the work from discovery through committee maintenance and voting.',{prototype:{url:'https://www.figma.com/proto/hn1KPlUQVOIlVMKbz1id6I?node-id=151-3362&starting-point-node-id=151-3362',poster:'house-vote',title:'U.S. House committee voting prototype',caption:'The working Figma prototype: find a referral, review its brief, and record a roll-call vote. Data shown is illustrative.'},items:[item('Find and review referrals.','Filter legislative activity and open the supporting brief.','house-dashboard','The referral dashboard combines scope, results, and detail actions.'),item('Maintain the roster.','Keep majority and minority membership organized for committee work.','house-roster','The roster editing view groups representatives for maintenance.'),item('Record a roll-call vote.','Review meeting context and record explicit representative choices.','house-vote','Roll-call context, tally, and voting controls belong to one view.')]}),
   section('A shared language for future committee work.','More than 30 reusable USWDS-based components supported filters, tables, forms, navigation, and voting. Figma specifications, Azure DevOps stories, and acceptance criteria carried those decisions into engineering.',{images:[['house-design-system','The component sheet: 18 of the 30+ components, from buttons and fields to alerts, modals, and table controls.'],['house-filters','Component anatomy: labels, field boundaries, selection affordances, and a reset action.'],['house-controls','Repeated voting controls establish the same choice structure for each representative.']]}),
   section('A clearer model of legislative work.','The project established a coherent product and implementation foundation. The outcomes below describe the delivered design work; no post-launch efficiency metric is claimed.',{items:[item('People','Staff and SMEs shaped pathways for locating referrals, reviewing context, and recording votes.'),item('Product','A new committee-voting experience connected referrals, rosters, and roll-call records.'),item('System','Reusable components and documented behavior gave engineering a foundation for continued development.')],images:[['house-vote-summary','The roll-call summary connects meeting information with the recorded disposition and outcome.']],quote:'My role was not to make legislative work simple. It was to make its complexity navigable.'})
  ]
 },
 libraryOfCongress:{
  number:'02',slug:'library-of-congress',client:'U.S. Copyright Office',title:'Enterprise UX Architecture',summary:'Creating a shared interaction framework for search, filtering, navigation, and administration across an interconnected federal product ecosystem.',tags:['Design systems','Enterprise UX','Accessibility','Information architecture'],
  hero:[['loc-user-search','Administration / A shared hierarchy for search, filters, and actions.'],['loc-advanced','Expert search / Structured criteria appear when the task needs precision.'],['loc-filter','Applications / Status and user filters refine an existing dataset.']],
  facts:[['Client','U.S. Copyright Office / Library of Congress'],['Product','Enterprise Copyright System ecosystem'],['Role','Design System Lead UX Designer'],['Timeline','March 2025 – July 2026'],['Team','Product, engineering, QA, accessibility partners, SMEs'],['Platform','Enterprise web applications'],['Tools','Figma, FigJam, Azure DevOps, Angular libraries'],['My ownership','Design audits, shared patterns, information architecture, search and filtering, components, accessibility specifications']],
  proof:[['16 months','Across the modernization ecosystem'],['Shared patterns','Search, navigation, feedback, and data'],['Multiple products','Administrative and remitter experiences']],
  sections:[
   section('Designing how an ecosystem should behave.','ECS applications had evolved across work streams over several years. My design-system work connected reusable components and guidance with the specialized needs of individual products.',{images:[['loc-users','User administration brings local navigation, search, filters, roles, and records into one workspace.']]}),
   section('Familiar tasks behaved differently.','As the ecosystem grew, teams repeatedly faced the same interaction questions. Search, filters, navigation, and feedback needed shared rules that could accommodate different tasks.',{items:[item('Navigation had to scale.','New capabilities needed a place in the hierarchy without making every destination equally prominent.'),item('Search needed a model.','Keyword lookup, advanced criteria, and results refinement solved different needs.'),item('Density needed priorities.','Data-heavy workspaces needed a clear relationship between primary actions, filters, and records.')],images:[['loc-filter','An Applications view combines status counts, user scope, and exclusions; each control has a different job.']]}),
   section('Audit behaviors across products.','I compared repeated interactions across existing and proposed screens, combined audits with stakeholder conversations, and mapped where shared behavior could help. Search and filtering became a useful test: one initiates a query, while the other narrows an existing set.',{images:[['loc-user-search','Administrative lookup scopes a user list by division, status, and application.'],['loc-advanced','Advanced remitter search combines an index and a term, with an option to add criteria.']]}),
   section('Consistency is behavioral.','The most useful standards explain what a control does and when a person needs it.',{items:[insight('Related styling is not enough.','Similar interfaces can still use different interaction rules.','Standardize behavior alongside visual anatomy.','Documented search, filter, reset, and state conventions support reuse.'),insight('Complexity should follow intent.','Expert searches need more precision than everyday lookups.','Reveal complexity according to the task.','Basic, advanced, and saved-search destinations separate levels of search.'),insight('Accessibility includes feedback.','Focus and errors need to be understandable beyond visual styling.','Specify interaction states with the component.','Field-level error text and visible focus became part of search behavior.')],images:[['loc-search-error','The advanced-search example shows required-field feedback beside a visible focus state.']]}),
   section('Define a language flexible enough to reuse.','Shared conventions should make specialized work easier to design, without flattening different workflows into identical screens.',{items:[item('Separate destinations from tasks.','Global products and local management areas need different levels of navigation. The administrative example keeps task-specific areas together.','loc-users','Local management navigation sits beside the user workspace.'),item('Offer levels of search.','A structured index-and-term query gives expert users precision without putting every criterion into the default lookup.','loc-index','The search-index menu exposes domain-specific criteria.'),item('Distinguish search from refinement.','Filters narrow results that already exist. Giving refinement its own place makes the current dataset and selected criteria easier to reason about.','loc-facets','Result facets show counts and selectable types of work.')]}),
   section('The same language, applied to different jobs.','These supplied screens show the patterns in context, from internal user administration to remitter applications and discovery.',{items:[item('User administration','Find users and narrow the list with operational filters.','loc-users','User details list with search, filters, role data, and actions.'),item('Remitter search','Choose a search mode, specify criteria, and refine the request.','loc-advanced','Advanced search offers repeatable index-and-term criteria.'),item('Applications','Use status and user scope to focus a table of applications.','loc-applications','Application records combine status, identifiers, and row actions.')]}),
   section('Document the interaction contract.','Shared Figma and Angular libraries connected foundations, components, patterns, and templates. Design reviews and the UX forum helped align teams around behavior and accessibility, while specifications carried those decisions into implementation.',{images:[['loc-search-error','Feedback layer: required-field text, focus treatment, and clear primary and secondary actions.'],['loc-filter','Data layer: status filters, selection controls, and the relationship to results.']]}),
   section('A foundation that could grow.','The deliverable was reusable guidance and a more explicit model of common interactions. These are design-system outcomes, rather than a claim of measured ecosystem-wide adoption or performance.',{items:[item('People','Teams gained a shared reference for discussing interaction and accessibility decisions.'),item('Product','Administrative and remitter experiences could draw from common search and filtering conventions.'),item('System','Behavior guidance complemented the component library, supporting future products and work streams.')],images:[['loc-user-search','Search anatomy in an applied workspace: consistent action hierarchy with product-specific filters.']],quote:'Enterprise consistency comes from making the rules of interaction predictable.'})
  ]
 },
 accounting:{
  number:'03',slug:'copyright-accounting',client:'U.S. Copyright Office',title:'Accounting & Payments Modernization',summary:'Translating financial rules, staff workflows, and legacy-system behavior into a clearer product model for Copyright Office accounting operations.',tags:['UX research','Workflow design','Legacy modernization','Financial systems'],
  hero:[['payments-legacy','The starting point / Legacy account, transaction, and allocation views.'],['payments-exception','The operational detail / Status and comments carry exception context.']],
  facts:[['Client','U.S. Copyright Office / Library of Congress'],['Domain','Registration accounting and payments'],['Role','UX Designer — Accounting Discovery'],['Timeline','March 2025 – July 2026'],['Team','Product, accounting SMEs, engineering, QA'],['Platform','Enterprise financial workspace'],['Tools','Figma, FigJam, Azure DevOps, legacy Siebel'],['My ownership','SME research, legacy analysis, workflow mapping, requirements translation, product modeling']],
  proof:[['Legacy → model','Understand before simplifying'],['Cross-team','Records, payments, and handoffs'],['Discovery','Requirements and proposed direction']],
  sections:[
   section('Understand why the complexity exists.','Modernizing accounting meant learning the relationships between payments, deposit accounts, registrations, and staff actions. The legacy interface was evidence of operational requirements accumulated over time.',{images:[['payments-legacy','Legacy Siebel account view: an account summary, transaction history, and payment-allocation area.']]}),
   section('A payment is more than an amount.','Different payment paths, account rules, and unresolved transactions created dependencies beyond any one form. Staff needed to understand both the record and its consequences.',{items:[item('Multiple entry paths','Paper checks, online payments, and other service paths could require different handling.'),item('Account lifecycle rules','Balance requirements, reminders, closure, and inactivation affected what could happen next.'),item('Exceptions crossed boundaries','Failed postings and unpaid records could require investigation across linked records.')],images:[['payments-transactions','Transactions carry balances, identifiers, posting status, and comments in the same operational view.']]}),
   section('Follow the records and the handoffs.','SME conversations clarified when payment records were created, which rules were already automated, and where accounting depended on other service units. I paired those findings with legacy analysis to frame requirements before proposing interface changes.',{images:[['payments-balance','The deposit-account summary exposes balance and account type as context for transactions.'],['payments-allocation','Payment allocation links a payment to downstream fees and service-request identifiers.']]}),
   section('Research changed what the product needed.','The discovery work helped distinguish a missing interface cue from a missing operational capability.',{items:[insight('Do not duplicate a working mechanism.','SMEs confirmed that low-balance replenishment reminders already existed.','Check operational behavior before proposing automation.','The product direction could prioritize account visibility instead of another reminder.'),insight('Creation is workflow-specific.','Some physical-payment paths required manual record creation.','Expose actions where the workflow and role require them.','Manual creation became a scoped requirement rather than an assumed global action.'),insight('Status needs an explanation.','A failed posting carried consequences that a short status alone could not explain.','Keep exception context beside the record.','Requirements needed to retain the relationship between status, comments, and linked records.')],images:[['payments-exception','The legacy status and comments columns show why an exception needs explanatory context.']]}),
   section('Simplify the model without losing the rules.','These decisions describe the discovery and proposed product direction. The supplied accounting artifacts show the current-state system, not a released replacement.',{items:[item('Keep account health close.','Treat balance and account type as decision context. This preserves important policy information while reducing the need to reconstruct account health from history.','payments-balance','Balance and account type are explicit in the account summary.'),item('Retain traceability.','Carry the relationship among transactions, allocations, and service records into requirements. A cleaner screen must still support investigation.','payments-allocation','Allocation fields expose the relationships that simplification must preserve.'),item('Prioritize exception understanding.','Pair a payment state with the information needed to interpret it. Dense legacy comments reveal an important need for actionable context.','payments-exception','Posting failures and fee adjustments appear alongside transaction state.')]}),
   section('Three views into the operational experience.','The current-state screens make the domain tangible: account context, movement of money, and the detail behind a financial record.',{items:[item('Account context','Begin with the account’s type and balance before interpreting a transaction.','payments-balance','Legacy account summary.'),item('Transaction investigation','Trace amounts, balances, identifiers, and status across a history.','payments-transactions','Legacy transaction history.'),item('Record detail','Inspect the accounting entry and its associated payment information.','payments-journal','Legacy account journal and record-detail fields.')]}),
   section('Connect domain rules to a shared product architecture.','Accounting discovery addressed records, refunds, service requests, permissions, batch locks, and audit needs. The enterprise UX work provided a related foundation for search and feedback; it was not evidence that a new accounting product had shipped.',{images:[['payments-allocation','Domain layer: preserve payment-to-service traceability in the product model.'],['loc-advanced','Related platform pattern: structured search offers a reusable approach to precise record lookup; this is a remitter screen.']]}),
   section('A stronger foundation for the next product decision.','The result was structured discovery and requirements clarity. The available evidence does not establish a released accounting replacement or measured financial-processing improvements.',{items:[item('People','SME knowledge became explicit input to product decisions and cross-team conversations.'),item('Product','Discovery clarified manual payment creation, existing reminders, and exception context.'),item('System','Linked records, lifecycle rules, permissions, and handoffs became part of the modernization model.')],images:[['payments-balance','An account balance is a decision input connected to policies, reminders, and account lifecycle.']],quote:'Understanding what should stay is as important as deciding what should change.'})
  ]
 },
 usda:{
  number:'04',slug:'usda',client:'USDA NASS',title:'Enterprise Application Modernization',summary:'Creating a reusable enterprise theme that connects user needs, accessible patterns, and implementation across internal agency applications.',tags:['Design systems','Research','Accessibility','Design to development'],figma:'https://www.figma.com/design/nHavJOvyWwlFQPdd3JBtRV/Web-Templates?m=auto&t=87B6SHcw49GcS0JP-6',
  hero:[['usda-navigation','Shared shell / Agency identity and application navigation.'],['usda-query','Data discovery / Structured criteria before results.'],['usda-alert','Feedback / A repeatable status pattern within the template.']],
  facts:[['Client','USDA National Agricultural Statistics Service'],['Product','Enterprise application theme and internal tools'],['Role','Sole UI/UX Designer'],['Timeline','December 2022 – August 2023'],['Team','Developers, product owner, SMEs, lead front-end developer'],['Platform','Responsive enterprise web applications'],['Tools','Figma, USWDS, Blazor, CSS, PostCSS, Bootstrap'],['My ownership','Surveys, personas, workflows, theme and components, prototypes, implementation collaboration, accessibility checks']],
  proof:[['6 months','To deploy the dynamic theme'],['Shared theme','Reusable across agency tools'],['Cross-device','Layouts and accessibility checks']],
  sections:[
   section('One foundation for many kinds of work.','Independently evolved applications needed familiar patterns without losing their specialized tasks. I designed a reusable theme and worked with the lead front-end developer to carry it into implementation.',{images:[['usda-admin','An applied enterprise screen: assigning users to a role within the shared USDA shell.']]}),
   section('Inconsistency added work for everyone.','Users had to learn different interfaces, while developers repeatedly recreated common patterns. The theme needed to balance agency standards, operational tasks, and the constraints of existing applications.',{items:[item('A familiar starting point','Navigation and hierarchy needed to remain recognizable between tools.'),item('Clear operational controls','Query builders, data tables, and permissions needed enough detail for internal users.'),item('Reusable access patterns','Responsive behavior and accessibility needed to travel with the components.')],images:[['usda-query','The Quick Stats selection interface shows the structured criteria and action hierarchy required for an agency task.']]}),
   section('Let the work shape the theme.','User surveys, personas, stakeholder conversations, and application audits identified recurring needs. Working alongside engineering helped connect those needs to components and layouts that could be implemented in the agency’s environment.',{images:[['usda-query','Selecting data is a distinct stage with several related criteria.'],['usda-results','The resulting table is a different task surface that still uses the same application language.']]}),
   section('The system has to serve real workflows.','Research and implementation collaboration shaped both the visual foundation and the patterns built on top of it.',{items:[insight('Research must travel into the library.','User needs extended beyond a single application screen.','Use recurring tasks to define reusable patterns.','The theme supported structured selection, data tables, and administrative layouts.'),insight('Consistency needs room for density.','Internal tools expose detailed records and controls.','Keep a shared shell while adapting the working area.','Query and results screens use familiar navigation with task-specific content.'),insight('Accessibility needs verification.','A design specification alone does not establish usable access.','Validate the implemented experience across devices.','Accessibility Insights and user testing supported cross-device checks.')],images:[['usda-components','The template demonstrates shared status feedback and accordion patterns inside the application shell.']]}),
   section('Build a theme that developers can carry forward.','Reusable decisions had to fit the implementation environment and remain flexible enough for multiple agency tools.',{items:[item('Standardize the shell.','Keep agency identity and navigation familiar while allowing the page body to fit the task.','usda-navigation','The shared header gives different applications a common frame.'),item('Preserve expert controls.','Simplifying a query interface cannot erase the criteria people need. Group related choices and make the transition to results explicit.','usda-query','Structured selections lead to Clear and Get Data actions.'),item('Design with implementation.','I partnered with the lead front-end developer across Blazor, CSS, PostCSS, and Bootstrap so the theme could become reusable working UI.','usda-alert','Status feedback is a concrete component to specify and implement consistently.')]}),
   section('A common frame, specialized tools.','The supplied screens show query construction, tabular results, and administrative access management within the same design language.',{items:[item('Choose the data.','Organize related criteria before requesting results.','usda-query','Quick Stats criteria and primary actions.'),item('Inspect the results.','Move from selection into a consistent table view.','usda-results','Quick Stats results table.'),item('Manage access.','Search users and work with role assignments.','usda-permissions','Assign Users to Role uses search and paired selection lists.')]}),
   section('Patterns that adapt across screens.','USWDS-informed foundations, reusable components, and responsive layouts created a system beyond individual mockups. Cross-device testing and accessibility checks accompanied the implementation work.',{images:[['usda-responsive','Existing mobile layout studies show how selection and result views adapt to narrower screens.'],['usda-components','The component template brings navigation, informative status, and expandable content together.']]}),
   section('A deployed theme and a reusable starting point.','The dynamic theme was deployed in six months. The work also established components and layouts for an internal directory experience; no quantified productivity improvement is claimed here.',{items:[item('People','Research and personas gave stakeholders a common reference for user needs.'),item('Product','A shared theme provided a consistent base for enterprise applications.'),item('System','Reusable layouts and implementation collaboration helped carry the design into agency tools.')],images:[['usda-navigation','The shared application shell is the visible foundation that carries between products.']],quote:'A strong internal system makes everyday work feel more familiar, even when the task changes.'})
  ]
 },
 athletico:{
  number:'05',slug:'athletico',client:'Athletico',title:'Patient Onboarding & Appointment Scheduling',summary:'Making the start of care more approachable through clearer onboarding, appointment access, and responsive patient-portal interactions.',tags:['Healthcare','User research','Responsive design','UI development'],figma:'https://www.figma.com/design/0W25IhXkLWlhytPD2Gl22g/Omoniyi-Portfolio?node-id=4-119566',
  hero:[['athletico-entry','Enter the portal / A focused welcome and sign-in area.'],['athletico-tasks','Find the next step / Care records and appointments have clear destinations.'],['athletico-appointments','Manage care / Appointment information on a narrow screen.']],
  facts:[['Client','Athletico Physical Therapy'],['Product','Patient onboarding and appointment experience'],['Role','UI Developer / design collaboration'],['Timeline','October 2021 – January 2023'],['Team','Product manager, UI/UX designer, developers'],['Platform','Responsive patient portal'],['Tools','Figma, HTML, JavaScript, CSS, Azure DevOps, PowerBuilder'],['My ownership','Wireframes and mockups with the designer, custom components, prototype refinement, accessibility testing']],
  proof:[['≈100','Participants in usability testing'],['Desktop + mobile','Responsive patient journeys'],['Design → build','Custom UI components']],
  sections:[
   section('A more human start to care.','The registration refresh aimed to make onboarding easier for patients and reduce the organizing work faced by customer-facing employees. I collaborated with the UI/UX designer and built custom components for the experience.',{images:[['athletico-overview','Existing portfolio composition: the portal welcome screen alongside appointment management.']]}),
   section('Uncertainty made an already demanding moment harder.','Patients had to navigate information requirements and appointment tasks while preparing for care. Research described uncertainty around required information, progress, and confirmation.',{items:[item('A clear point of entry','Patients needed to understand how to enter the experience and what they could do there.'),item('An understandable next step','Registration and scheduling needed a more coherent sequence.'),item('Less coordination effort','Customer-facing staff also needed a more efficient onboarding process.')],images:[['athletico-entry','The welcome and sign-in area creates a focused entry point before exposing the rest of the portal.']]}),
   section('Follow the patient and the supporting staff.','Interviews, surveys, workflow mapping, and prototype feedback informed the refresh. Testing with approximately 100 participants helped the team refine navigation, forms, and scheduling interactions. The visuals here show the interface informed by that work, rather than research-session artifacts.',{images:[['athletico-home','The post-login home groups patient tasks into recognizable destinations.'],['athletico-appointments','The mobile appointment view brings upcoming and past care information into a focused list.']]}),
   section('Efficiency should feel reassuring.','Small choices about hierarchy and access influence how confidently someone can move through a care journey.',{items:[insight('The next step must be recognizable.','Patients faced uncertainty in the onboarding journey.','Give each stage a clear purpose.','The entry experience establishes sign-in, with patient tasks revealed inside the portal.'),insight('Staff needs are part of the journey.','Employees spent time organizing patient onboarding.','Consider the service around the interface.','Registration work was designed around both patient clarity and staff coordination.'),insight('Care continues across devices.','Patients needed portal access beyond a desktop screen.','Preserve task hierarchy on smaller screens.','Responsive home and appointment views retain recognizable destinations.')],images:[['athletico-tasks','The task grid gives care records, appointments, billing, and patient content separate, legible destinations.']]}),
   section('Make the next action easier to recognize.','The team worked from wireframes and mockups into components, using feedback to refine the interface before delivery.',{items:[item('Focus the entry point.','Keep the welcome and login form together, with supporting resources nearby. This balances a clear primary action with practical patient needs.','athletico-entry','Welcome text and account entry share a focused area.'),item('Use task-based destinations.','Give appointments and care information explicit names. The grid prioritizes recognition instead of asking people to interpret a dense menu.','athletico-tasks','Patient tasks use a repeated icon, title, and description pattern.'),item('Adapt the layout to the device.','Move from a desktop workspace to a narrow task view while preserving recognizable labels and actions.','athletico-mobile','The mobile home retains the same core patient destinations.')]}),
   section('From entering the portal to managing care.','The available artifacts show the welcome screen, patient home, and appointment-management views. They illustrate those parts of the broader onboarding and scheduling work.',{items:[item('Enter with a clear purpose.','A welcome, sign-in fields, and patient resources establish the starting point.','athletico-login','Desktop patient-portal welcome and sign-in.'),item('Choose a care task.','Navigate to appointments or care records from a familiar home.','athletico-home','Desktop home after login.'),item('Review appointments on mobile.','Read care dates and details in a layout designed for a narrow screen.','athletico-appointments','Mobile Episodes of Care view with upcoming and past tabs.')]}),
   section('Carry the design into reliable components.','Custom HTML, JavaScript, and CSS components connected the agreed designs to implementation. Azure DevOps and PowerBuilder supported delivery, while Accessibility Insights and WAVE supported accessibility checks.',{images:[['athletico-tasks','Repeated task cards provide a consistent title and action hierarchy.'],['athletico-mobile-login','The narrow-screen entry retains account fields and patient resources in a vertical layout.']]}),
   section('A refreshed journey, supported by testing.','The work delivered refreshed registration UI, custom components, and accessibility testing. The available portfolio material documents approximately 100 test participants; it does not isolate a causal business impact for these interface changes.',{items:[item('People','Patient and employee needs were considered together in the onboarding work.'),item('Product','A refreshed portal connected entry, care tasks, and appointment access.'),item('System','Reusable front-end components supported responsive delivery and accessibility verification.')],images:[['athletico-appointments','Appointment details stay visible in a focused mobile care view.']],quote:'The most helpful healthcare experiences make the next step feel obvious—without making the person taking it feel rushed.'})
  ]
 }
 ,wedding:{
  number:'06',slug:'wedding-identity',client:'Independent studio work',title:'Wedding Identity & Guest Experience',summary:'Extending an established visual world into an original emblem, keepsakes, and décor for a wedding weekend that brings together Black American and Armenian heritage.',tags:['Creative direction','Illustration','Experience design','Visual systems'],
  chapters:['Snapshot','The Brief','Reading the Couple','The Emblem','Carrying the World','Outcome & Reflection'],
  hero:[['wedding-emblem-cream','The mark / Cowrie shells and pomegranates woven into one emblem.'],['wedding-emblem-blue','The palette / Steel blue carries the linework in cream.']],
  facts:[['Client','Boutique event-design studio (anonymized)'],['Project','Wedding identity & guest experience'],['Role','Creative direction & illustration'],['Timeline','September 2026 · one week'],['Format','Solo design trial'],['Setting','Spring wedding at a Northern California vineyard inn'],['Deliverables','Emblem in four colorways, eight décor concepts, tablescape direction'],['My ownership','Concept, illustration, décor and keepsake direction, tablescape curation']],
  proof:[['1 emblem','Four colorways'],['8','Décor & keepsake concepts'],['1 week','From brief to submission']],
  sections:[
   section('A visual world for a two-heritage celebration.','A boutique event-design studio invited me to extend the world it had already built for a couple’s wedding weekend. The couple’s names shown in the artwork are placeholders; the real couple and studio are kept private.',{images:[['wedding-emblem-cream','The arch colorway: the emblem opened around a name band, sized for menus and signage.']]}),
   section('Extend the world without breaking it.','The couple wanted a room that shapes your mood rather than fading into the background: considered, culturally alive, and never templated. The studio’s guardrails were as useful as the brief itself.',{items:[item('Stay inside the system.','Use the palette, fonts, and motifs already established. Nothing new unless it grows from what exists.'),item('Make culture considered, not decorative.','Black American and Armenian references needed to carry meaning, not sit on the surface as ornament.'),item('Reward a second look.','No fake flowers, no arches, no overdone glam. Details should reveal a story to the guests who notice them.')]}),
   section('Read the intake like research.','The couple’s intake read like a research artifact: rooms and architecture that shape a mood, the Black diasporic visual storytelling and soul records they love, and handmade objects already in their home. I treated each reference as evidence for what the celebration should feel like.',{items:[item('Two heritages, one point of view.','The work needed to hold two distinct identities without blending either into something generic.'),item('Their objects already tell the story.','A wine collection, ceramics from a pottery date, and a handmade lamp pointed toward keepsakes guests could hold.'),item('Intimate, not performed.','The celebration was a welcome into who they already are together, so every detail had to feel personal rather than staged.')]}),
   section('A symbol that holds both stories.','Cowrie shells carry associations with protection and meaning within Black American culture; the pomegranate nods to Armenian heritage. Woven through curling stems, the motifs stay distinct inside one shared point of view. A braided border stands in for the soft but strong bond the couple is confirming, and wraps them in a continuous oval designed to travel across menus, a custom newspaper, and keepsake packaging.',{items:[item('Steel blue','Cream linework on steel blue for signage and printed pieces.','wedding-emblem-blue','Oval colorway in cream on steel blue.'),item('Brick red on blush','Tonal red for warmer paper goods and packaging.','wedding-emblem-pink','Oval colorway in brick red on blush.'),item('Brick red on lavender','A softer ground for keepsakes, holding the same linework.','wedding-emblem-lavender','Oval colorway in brick red on lavender.')]}),
   section('Eight details that live across the day.','The emblem only works if it travels. Each concept extends the palette and the story into something guests touch, taste, or take home. The table direction pairs hard surfaces softened by draping, color used boldly enough to shape the room, and fruit and greenery built into the table itself.',{items:[item('Plinth florals','Concrete, mirrored, and clear plinths holding brick-red flowers with pops of blue: hard structure softened by organic form.'),item('A table of fruit','Split pomegranates, brushed metals, and draping that carry the color story and the Armenian lineage onto the table.'),item('Engraved decanters','Collected silhouettes that nod to the couple’s love of wine and give guests an object to gather around.'),item('Matchbox keepsakes','Engraved mixed-metal matchboxes displayed on trays over steel-blue or brick-red silk, tying together fire, scent, and memory.'),item('Projected story','Photos and film projected across draped fabric through the evening, ending in a deliberately theatrical moment at the cake cutting.'),item('Drinks on ice','Signature cocktails in silver or brushed-metal cups on sculptural ice, passed out as part of the experience.'),item('Message booth','A booth where friends and family leave notes for the newlyweds; it doubles as a photo booth for the night.'),item('Candle keepsake','A ceramic candle in a scent of the couple’s choosing, inscribed with the date and their initials.')]}),
   section('What a one-week trial can show.','The trial was submitted to the studio as a proposal. It was not produced, so no event outcome is claimed; what it demonstrates is how I carry one idea from a symbol to a room.',{items:[item('People','A couple’s intake translated into details that reflect who they are, not a template.'),item('Product','An original emblem and a set of décor and keepsake concepts built from the same visual language.'),item('System','One mark, four colorways, and rules for carrying it across paper, objects, and space.')],quote:'The best details don’t decorate a room. They tell guests who they’re celebrating.'})
  ]
 }
 ,portfolio:{
  number:'07',slug:'portfolio-ecosystem',client:'Self-initiated',title:'One Designer, Three Audiences, One System',summary:'Designing and building a portfolio that holds my product work, my studio, a UI kit, and my writing, without making the story harder to read.',tags:['Information architecture','Product design','Visual systems','Front-end build'],
  chapters:['Snapshot','Problem','Audiences','Decisions','The System','How This Site Moves','Outcome & Reflection'],
  hero:[['portfolio-hiring','Someone hiring / Positioning, case studies, and the résumé come first.'],['portfolio-building','Someone building / The same page leads with Studio and LaunchKit.']],
  facts:[['Project','omoniyialimi.com, self-initiated'],['Role','Sole designer and builder'],['Primary audience','Recruiters, hiring managers, founders, design-led teams'],['Secondary audiences','Studio clients, LaunchKit users, readers'],['Surfaces','Portfolio, Studio, LaunchKit UI, Observations'],['Tools','Figma, React, Vite, Netlify, GA4'],['Timeline','July 2026 – ongoing'],['My ownership','Strategy, information architecture, copy, visual design, front-end build, analytics']],
  proof:[['2','Reading modes: someone hiring, someone building'],['4','Connected spaces in one ecosystem'],['1','Point of view holding it together']],
  sections:[
   section('The portfolio had outgrown the portfolio format.','My site started as a traditional portfolio: selected work, an about page, a way to get in touch. Then my practice grew. I was building Omoniyi Studio, developing LaunchKit UI, writing Observations, and positioning for senior product roles. The problem wasn’t fitting more into the navigation. It was letting all of it belong to the same designer without making the story harder to understand.',{images:[['portfolio-hiring','The homepage in hiring mode: the positioning, the selected-work stack, and the résumé within one screen.']]}),
   section('The more I added, the less the site explained.','Three kinds of visitor were arriving with three different jobs. A recruiter needs to know, fast: what kind of designer is she, what problems is she good at, can she handle complexity, and what did she actually own? Treating every visitor the same would have made the site simpler to build and harder to understand.',{items:[item('Someone hiring','Needs specialization quickly: complex systems, product thinking, ownership, and proof.'),item('Someone building','Needs to believe I can shape an idea from a messy beginning into something that ships.'),item('Someone using the kit','Needs to see that systems thinking is something I practice independently, not just describe.')]}),
   section('So I treated the website like a product.','Instead of asking what sections a portfolio should have, I started with one question: what does each person need to understand before they know where to go next? The answer kept the portfolio at the center and turned everything else into supporting evidence: separate doors into the same practice.',{items:[item('Omoniyi Studio','How I think when the starting point is a business, a rough idea, or a visual problem.','portfolio-studio','Studio: diagnosis, design, build, and improvement as one path.'),item('LaunchKit UI','Systems thinking, reusable patterns, and component architecture, built as a product.','portfolio-uikit','LaunchKit UI: a free kit that grows into Pro.'),item('Observations','The references, media, and ideas that shape the work, kept visible.','portfolio-observations','Observations: reference, then thought, then output.')]}),
   section('Four decisions that held it together.','Each one trades a little simplicity for a lot of clarity. Together they let the site change emphasis without changing who I am.',{items:[item('Design for intent, not for everyone.','A two-way switch asks who’s reading. Someone hiring sees complex systems, ownership, and the résumé. Someone building sees “Bring me the rough idea.” The tradeoff: one more interaction to maintain, instead of diluting the hiring message to sell services.','portfolio-building','The building view of the same hero.'),item('Make complexity the positioning, not the aesthetic.','Instead of listing disciplines, the site names the transformation I keep making: complex systems, made clear. Every case study follows one anatomy so readers can compare projects instead of relearning each one.','portfolio-work','The Work page: every study shares one structure.'),item('Use a notebook as the interface metaphor.','Warm paper, strong type, a visible grid, stamps, and handwriting. The grid provides order; the annotations provide personality. The texture stays restrained so enterprise screens still read cleanly.','portfolio-mobile','The notebook language holds on a phone.'),item('Give each space its own voice and one grammar.','If the portfolio feels like field notes, Studio feels like the design office they lead to. Navigation keeps the portfolio primary, with Studio and LaunchKit one step away, held together by shared type, spacing, and a common switcher.','portfolio-studio','Studio’s parchment, ink, and oxblood dialect.')]}),
   section('Infrastructure, not a finished portfolio.','A portfolio also lives in LinkedIn posts, job applications, messages, and search results. Every part of the site needed to make sense before anyone clicked, and to keep working as new things arrive.',{items:[item('Previews are part of the UX.','Each route is prerendered with its own title, description, and preview image, so shared links read correctly without running JavaScript. The sitemap is generated from the same data.'),item('Content is data.','Case studies, résumés, and page metadata live in structured data. A new case study is one entry, not a redesign, and both résumés are built from one set of facts.'),item('The funnel is instrumented.','GA4 events track résumé views, studio inquiries, form starts, bookings, and LaunchKit clicks, so decisions about the site come from how people use it.')],images:[['portfolio-og-home','Portfolio link preview.'],['portfolio-og-studio','Studio link preview, same family, its own voice.']]}),
   section('One motion scale, three personalities.','Motion on the site follows the same rule as the rest of the system: one shared set of timings, with each space choosing a personality from it. Everyday feedback is quick and gets out of the way; brand moments are slower and rarer. Nothing moves just to be seen, and everything has a still version.',{items:[item('Portfolio: hand-placed','A soft spring with about 4% overshoot, small resting tilts, and pen marks that ink themselves once. It should feel like someone arranging notes on a desk.'),item('Studio: typeset','Long, calm ease-out settles with no bounce and no rotation. The office the notes lead to moves like type being set, not paper being shuffled.'),item('LaunchKit: productive','Productive curves only, 150–240 ms, no rotation. Motion there exists to show component states, because that is what builders are evaluating.')],table:{caption:'Motion spec: the site’s key interactions',head:['Interaction','Element','Property','Duration','Easing','Reduced motion'],rows:[['Open a case study','Work card → case-study header','Shared-element morph (View Transitions API)','420 ms','Expressive standard','Instant page change'],['Swap reading mode','Hero headline and actions','Opacity, position','200–240 ms','Productive standard','Instant swap'],['Browse selected work','Paper card stack','Transform (tear away, settle)','320 ms','Hand-placed spring','Instant, no tilt'],['Annotate','Pen mark under a note','Stroke draw, once on first view','700 ms','Pen','Shown already drawn'],['Ambient sky','Star dust canvas','Particle drift','Continuous','—','Paused; one still frame; pause control always visible'],['Hover feedback','Cards, links, buttons','Lift, colour','150–200 ms','Productive standard','Colour change only']]}}),
   section('Range got easier to read once it had a point of view.','The hardest part of designing for yourself isn’t visual design. It’s deciding what deserves emphasis. I first treated range as something to explain; it turned out range is easy to understand when a strong point of view connects it. Analytics went live in September 2026, so no conversion result is claimed yet.',{items:[item('For hiring teams','Product thinking, complex systems, ownership, and visual craft come first, with a résumé tailored to the role.'),item('For founders','Studio translates the same abilities into a clear service, from diagnosis to build.'),item('For builders','LaunchKit turns my systems thinking into something other people can use.')],quote:'The goal was never to make everything look the same. It was to make it obvious the same person was thinking behind all of it.'})
  ]
 }
};
